const WebSocket = require('ws');
const crypto = require('crypto');
const fs = require('fs');

const ALGORITHM = 'aes-256-cbc';
const KEY = crypto.randomBytes(32);
const STORAGE_PATH = '/tmp/secure_store';

class EncryptedStorage {
  constructor() {
    this.store = new Map();
  }

  encrypt(plaintext) {
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv(ALGORITHM, KEY, iv);
    cipher.setAutoPadding(true);
    let encrypted = cipher.update(plaintext, 'utf8', 'hex');
    encrypted += cipher.final('hex');
    return iv.toString('hex') + ':' + encrypted;
  }

  decrypt(ciphertext) {
    const parts = ciphertext.split(':');
    if (parts.length !== 2) {
      return { success: false, error: 'INVALID_FORMAT' };
    }
    const iv = Buffer.from(parts[0], 'hex');
    const encrypted = parts[1];
    if (iv.length !== 16) {
      return { success: false, error: 'INVALID_IV' };
    }
    try {
      const decipher = crypto.createDecipheriv(ALGORITHM, KEY, iv);
      decipher.setAutoPadding(true);
      let decrypted = decipher.update(encrypted, 'hex', 'utf8');
      decrypted += decipher.final('utf8');
      return { success: true, data: decrypted };
    } catch (err) {
      if (err.message.includes('bad decrypt') || err.message.includes('wrong final block')) {
        return { success: false, error: 'PADDING_ERROR' };
      }
      return { success: false, error: 'DECRYPTION_FAILED' };
    }
  }

  set(key, value) {
    const encrypted = this.encrypt(JSON.stringify(value));
    this.store.set(key, encrypted);
    return true;
  }

  get(key) {
    const encrypted = this.store.get(key);
    if (!encrypted) return { success: false, error: 'NOT_FOUND' };
    return this.decrypt(encrypted);
  }

  validateToken(token) {
    return this.decrypt(token);
  }
}

const storage = new EncryptedStorage();

function createAuthToken(userId) {
  const payload = JSON.stringify({
    userId,
    exp: Date.now() + 3600000,
    nonce: crypto.randomBytes(8).toString('hex')
  });
  return storage.encrypt(payload);
}

function handleMessage(ws, message) {
  let parsed;
  try {
    parsed = JSON.parse(message);
  } catch (e) {
    ws.send(JSON.stringify({ error: 'PARSE_ERROR' }));
    return;
  }

  const { action, payload } = parsed;

  switch (action) {
    case 'login': {
      const { username, password } = payload || {};
      if (username === 'admin' && password === 'secret') {
        const token = createAuthToken(username);
        ws.send(JSON.stringify({ success: true, token }));
      } else {
        ws.send(JSON.stringify({ success: false, error: 'AUTH_FAILED' }));
      }
      break;
    }

    case 'verify': {
      const { token } = payload || {};
      if (!token) {
        ws.send(JSON.stringify({ success: false, error: 'NO_TOKEN' }));
        return;
      }
      const result = storage.validateToken(token);
      ws.send(JSON.stringify(result));
      break;
    }

    case 'store': {
      const { token, key, value } = payload || {};
      if (!token) {
        ws.send(JSON.stringify({ success: false, error: 'NO_TOKEN' }));
        return;
      }
      const auth = storage.validateToken(token);
      if (!auth.success) {
        ws.send(JSON.stringify(auth));
        return;
      }
      storage.set(key, value);
      ws.send(JSON.stringify({ success: true }));
      break;
    }

    case 'retrieve': {
      const { token, key } = payload || {};
      if (!token) {
        ws.send(JSON.stringify({ success: false, error: 'NO_TOKEN' }));
        return;
      }
      const auth = storage.validateToken(token);
      if (!auth.success) {
        ws.send(JSON.stringify(auth));
        return;
      }
      const data = storage.get(key);
      ws.send(JSON.stringify(data));
      break;
    }

    default:
      ws.send(JSON.stringify({ error: 'UNKNOWN_ACTION' }));
  }
}

const wss = new WebSocket.Server({ port: 8080 });

wss.on('connection', (ws) => {
  ws.on('message', (message) => {
    handleMessage(ws, message.toString());
  });
});

